debug_text.text:
'RescueRangers [%s at %s, Mode: %s] - %s, our : %s (class: %s, macro: %s, type: %s - %s) in sector: %s. Killer: %s {%s}, method: %s. Spacesuit docked: %s. Crew free: %s'
            .[
              this.assignedcontrolled.debugname,
              this.assignedcontrolled.sector.knownname,
              @$rescueMode,
              @event.name,
              @event.param.debugname,
              @event.param.class,
              @event.param.macro,
              @event.param.type,
              @event.param.typename,
              @event.param.sector.knownname,
              @event.param2.debugname,
              @event.param2.class,
              @event.param3,
              event.param == $target,
              this.assignedcontrolled.people.free,
            ]

'RescueRangers [%s at %s, Mode: %s] - Event %s : %s {%s} status: iswreck: %s, isoperational: %s,  pilot: %s (%s), param: %s {%s}, , param2: %s {%s}, target: %s'
            .[
              this.assignedcontrolled.debugname,
              this.assignedcontrolled.sector.knownname,
              @$rescueMode,
              event.name,
              @event.object.debugname,
              @event.object.class,
              @event.object.iswreck,
              @event.object.isoperational,
              @event.object.pilot,
              event.object.pilot?,
              @event.param.debugname,
              @event.param.class,
              @event.param2.debugname,
              @event.param2.class,
              $target,
            ]

'RescueRangers [%s at %s, Mode: %s] - This ship people: free: %s, total: %s, capacity: %s, service: %s, marine: %s, unassigned: %s'
            .[
              this.assignedcontrolled.debugname,
              this.assignedcontrolled.sector.knownname,
              @$rescueMode,
              this.assignedcontrolled.people.free,
              @this.assignedcontrolled.people.count,
              @this.assignedcontrolled.people.capacity,
              @this.assignedcontrolled.people.{entityrole.service}.count,
              @this.assignedcontrolled.people.{entityrole.marine}.count,
              @this.assignedcontrolled.people.{entityrole.unassigned}.count,
            ]

'RescueRangers [%s at %s, Mode: %s] - Aborted Base Order. Order: %s, is running: %s. '
        .[
          @this.assignedcontrolled.debugname,
          @this.assignedcontrolled.sector.knownname,
          @$rescueMode,
          @this.assignedcontrolled.order.id,
          @this.assignedcontrolled.order.isrunning,
        ]
